using namespace std;
typedef long long ll;

int main() {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;
    vector<pair<ll, ll>> targets(n), sat(m);
    for (auto &[l, r] : targets) scanf("%lld %lld", &l, &r);
    for (auto &[l, r] : sat) scanf("%lld %lld", &l, &r);
    sort(targets.begin(), targets.end());
    sort(sat.begin(), sat.end());
    ll end = LLONG_MIN;  // covered up to here by chosen satellites
    int idx = 0, answer = 0;
    for (auto [left, right] : targets) {
        if (end >= right) continue;
        ll point = max(left, end);  // leftmost uncovered point of this target
        while (point < right) {
            // Among satellites starting at or before point, take the farthest end.
            ll far = point;
            while (idx < m && sat[idx].first <= point) far = max(far, sat[idx++].second);
            if (far <= point) { puts("-1"); return 0; }
            answer++;
            end = point = far;
        }
    }
    printf("%d\n", answer);
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));
        int n = (int) readLong(in), m = (int) readLong(in);
        long[][] targets = new long[n][2], sat = new long[m][2];
        for (long[] t : targets) { t[0] = readLong(in); t[1] = readLong(in); }
        for (long[] s : sat) { s[0] = readLong(in); s[1] = readLong(in); }
        Comparator<long[]> byPair = (a, b) -> a[0] != b[0] ? Long.compare(a[0], b[0]) : Long.compare(a[1], b[1]);
        Arrays.sort(targets, byPair);
        Arrays.sort(sat, byPair);
        long end = Long.MIN_VALUE; // covered up to here by chosen satellites
        int idx = 0, answer = 0;
        for (long[] t : targets) {
            if (end >= t[1]) continue;
            long point = Math.max(t[0], end); // leftmost uncovered point of this target
            while (point < t[1]) {
                // Among satellites starting at or before point, take the farthest end.
                long far = point;
                while (idx < m && sat[idx][0] <= point) far = Math.max(far, sat[idx++][1]);
                if (far <= point) { System.out.println(-1); return; }
                answer++;
                end = point = far;
            }
        }
        System.out.println(answer);
    }

    static long readLong(DataInputStream in) throws IOException {
        int b = in.read();
        while (b != '-' && (b < '0' || b > '9')) b = in.read();
        boolean neg = false;
        if (b == '-') { neg = true; b = in.read(); }
        long r = 0;
        while (b >= '0' && b <= '9') { r = r * 10 + (b - '0'); b = in.read(); }
        return neg ? -r : r;
    }
}

package main

import (
	"bufio"
	"cmp"
	"fmt"
	"math"
	"os"
	"slices"
)

type seg struct{ l, r int64 }

func readInt(in *bufio.Reader) int64 {
	b, _ := in.ReadByte()
	for b != '-' && (b < '0' || b > '9') {
		b, _ = in.ReadByte()
	}
	neg := false
	if b == '-' {
		neg = true
		b, _ = in.ReadByte()
	}
	var r int64
	for b >= '0' && b <= '9' {
		r = r*10 + int64(b-'0')
		b, _ = in.ReadByte()
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<16)
	n, m := int(readInt(in)), int(readInt(in))
	targets, sat := make([]seg, n), make([]seg, m)
	for i := range targets {
		targets[i] = seg{readInt(in), readInt(in)}
	}
	for i := range sat {
		sat[i] = seg{readInt(in), readInt(in)}
	}
	byPair := func(a, b seg) int { return cmp.Or(cmp.Compare(a.l, b.l), cmp.Compare(a.r, b.r)) }
	slices.SortFunc(targets, byPair)
	slices.SortFunc(sat, byPair)
	end := int64(math.MinInt64) // covered up to here by chosen satellites
	idx, answer := 0, 0
	for _, t := range targets {
		if end >= t.r {
			continue
		}
		point := max(t.l, end) // leftmost uncovered point of this target
		for point < t.r {
			// Among satellites starting at or before point, take the farthest end.
			far := point
			for idx < m && sat[idx].l <= point {
				far = max(far, sat[idx].r)
				idx++
			}
			if far <= point {
				fmt.Println(-1)
				return
			}
			answer++
			end, point = far, far
		}
	}
	fmt.Println(answer)
}
